#[test]
fn animation_set_v1_is_rejected_instead_of_implicitly_migrated() {
    assert!(matches!(
        AnimationSet::from_json(r#"{"schema_version":1,"graph":null,"bindings":{}}"#),
        Err(AnimationSetError::UnsupportedVersion { found: 1 })
    ));
}

